"""본문 UI와 실행 파일을 함께 보관합니다. GitHub 업로드에서 ui/dist가 빠져도 복구합니다."""
import base64
import hashlib
import io
import os
from pathlib import Path
import tempfile
import threading
import zipfile
import streamlit as st
import streamlit.components.v1 as components

_ASSET_HASHES={
    "ANIMATED_CONTENT_LICENSE.md": "4bdd1fa59a6b7d5954bc3b213dbc34e455c635a94bbcecf9293553797d0fad02",
    "app.css": "e3385d9946c9e85f541148a87120ab897cb52751c88086c4adb31f2fe376192d",
    "app.js": "f944ab2ecd3862c99da79ed826f1b3bfca940e9244c2f2ddc4936fa0740a2991",
    "app.js.LEGAL.txt": "6057fe3e880ebcbd7362eb94b9653ac24346fd008480d1026cec854b514a8209",
    "FADE_CONTENT_LICENSE.md": "f4c33af6739191537738662d223b68d77bc226f4b57ea883e16481d8cc5c73c9",
    "GSAP_NOTICE.txt": "ad7aaf2dd8e2ee26c8b498852f46f4c8aeedf5b363d3110c164f9f1e0b7bde35",
    "index.html": "b65e39cd5702563e12e4238d8ca7d0d01ad8231c661315cc38131c82c0377995",
    "PULSE_HEART_LICENSE.md": "4bdd1fa59a6b7d5954bc3b213dbc34e455c635a94bbcecf9293553797d0fad02",
    "REACT_BITS_LICENSE.md": "4bdd1fa59a6b7d5954bc3b213dbc34e455c635a94bbcecf9293553797d0fad02"
}
_BUNDLE_HASH='528f56c76827728186b88f63923597814664a5662444bca06f8c9fd8593073dc'
_ASSET_LOCK=threading.RLock()


def _assets_directory(cache_root=None):
    """신뢰하는 내장 자료만 검증하고 전용 캐시에 복원하며 앱·DB 디렉터리는 공개하지 않습니다."""
    with _ASSET_LOCK:
        return _restore_assets(cache_root)


def _restore_assets(cache_root):
    base=Path(cache_root) if cache_root is not None else Path(tempfile.gettempdir())/"pnu-link-body-ui"
    target=base/f"{_BUNDLE_HASH}-{os.getpid()}"
    target.mkdir(parents=True,exist_ok=True)
    if target.is_symlink() or target.resolve().parent!=base.resolve():
        raise RuntimeError("UI cache path is invalid")
    def valid(name):
        path=target/name
        return path.is_file() and not path.is_symlink() and path.stat().st_size<=2_000_000 and hashlib.sha256(path.read_bytes()).hexdigest()==_ASSET_HASHES[name]
    if all(valid(name) for name in _ASSET_HASHES):
        return target.resolve()
    packed=base64.b85decode(b"".join(_BUNDLE.split()))
    if hashlib.sha256(packed).hexdigest()!=_BUNDLE_HASH:
        raise RuntimeError("Embedded UI integrity check failed")
    with zipfile.ZipFile(io.BytesIO(packed)) as archive:
        if set(archive.namelist())!=set(_ASSET_HASHES) or len(archive.namelist())!=len(_ASSET_HASHES):
            raise RuntimeError("Embedded UI files are invalid")
        for name,digest in _ASSET_HASHES.items():
            if Path(name).name!=name or name in (".","..") or archive.getinfo(name).file_size>2_000_000:
                raise RuntimeError("Embedded UI asset is invalid")
            content=archive.read(name)
            if hashlib.sha256(content).hexdigest()!=digest:
                raise RuntimeError("Embedded UI integrity check failed")
            # 동시에 시작한 세션에서도 완성된 파일만 보이도록 원자적으로 교체합니다.
            descriptor,temporary=tempfile.mkstemp(prefix=".asset-",dir=target)
            try:
                with os.fdopen(descriptor,"wb") as output:
                    output.write(content)
                os.replace(temporary,target/name)
            finally:
                Path(temporary).unlink(missing_ok=True)
    return target.resolve()


