ynZVL000aK000#L0000000000004ji5(NSPQbj>SR9`|#R8wC}Nkc_WQ$;RqWKc^51^@s600{sI05Jjp0B{Kc0000"""

_catalog=components.declare_component("pnu_catalog",path=str(_assets_directory()))


def render(data,key,on_favorite=None):
    # 관심 저장 콜백을 먼저 처리해 새 상태를 한 번의 목록 갱신에 반영합니다.
    def changed():
        event=st.session_state.get(key)
        if (not isinstance(event,dict) or event.get("action")!="favorite" or on_favorite is None
                or not isinstance(event.get("event"),str) or not 1<=len(event["event"])<=80
                or st.session_state.get(key+"_event")==event["event"]):
            return
        st.session_state[key+"_event"]=event["event"]
        ok=bool(on_favorite(event))
        st.session_state[key+"_ack"]={"event":event["event"],"id":event.get("id"),"ok":ok}
    data={**data,"ack":st.session_state.get(key+"_ack")}
    event=_catalog(data=data,key=key,default=None,on_change=changed if on_favorite else None)
    if not isinstance(event,dict) or not isinstance(event.get("event"),str) or not 1<=len(event["event"])<=80:
        return None
    if st.session_state.get(key+"_event")==event["event"]:
        return None
    st.session_state[key+"_event"]=event["event"]
    return event
